using System;using System.Drawing;using System.Windows.Forms;using SargasPC;using Sargon.Setup;using System.Reflection;
class CompletionUI {
 static void Dialog(Window window,string method,string title){bool found=false;using(var timer=new Timer{Interval=200}){timer.Tick+=(s,e)=>{foreach(Form form in Application.OpenForms){if(form.Text!=title)continue;Application.DoEvents();Layout(form);if(title=="Papildomos MalwareBazaar sumos"){int disabled=0;bool config=false;foreach(Control panel in form.Controls)foreach(Control b in panel.Controls){if(b is Button&&!b.Enabled)disabled++;if(b is Button&&b.Enabled&&b.Text.StartsWith("Įvesti"))config=true;}if(disabled!=2||!config)throw new Exception("Missing-key download gate or key configuration missing");Console.WriteLine("Feed access UI: missing key disables both download actions; key settings remain available; no request sent.");}if(title=="Vietinis ClamAV variklis"){bool disabled=false;foreach(Control panel in form.Controls)foreach(Control b in panel.Controls)if(b is Button&&b.Text.StartsWith("1."))disabled=!b.Enabled;if(!disabled)throw new Exception("shared engine provision button enabled");}found=true;timer.Stop();form.Close();break;}};timer.Start();typeof(Window).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[0]);if(!found)throw new Exception("missing "+title);}}
 static void Layout(Control c){foreach(Control child in c.Controls){if(!child.Visible)continue;if(child.Right>c.ClientSize.Width+2||child.Bottom>c.ClientSize.Height+2)throw new Exception("Outside: "+child.Text+" "+child.Bounds+" in "+c.ClientRectangle);Layout(child);}}
 [STAThread]static void Main(){Application.EnableVisualStyles();using(var window=new Window(new Core(System.IO.Path.Combine(System.IO.Path.GetTempPath(),"sargon38-ui-"+Guid.NewGuid())))){using(var timer=new Timer{Interval=200}){bool found=false;timer.Tick+=(s,e)=>{foreach(Form form in Application.OpenForms){if(form.Text!="Bendra SARGON parengtis")continue;Layout(form);found=true;timer.Stop();form.Close();break;}};timer.Start();typeof(Window).GetMethod("UnifiedReadinessDialog",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[0]);if(!found)throw new Exception("readiness missing");}window.Font=new Font("Segoe UI",14);Dialog(window,"SimpleUpdates","Atnaujinimai");Dialog(window,"FeedDialog","Papildomos MalwareBazaar sumos");Dialog(window,"FindingsChoice","Peržiūrėti radinius");((Core)typeof(Window).GetField("core",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(window)).SharedReadOnlyEngine=true;Dialog(window,"LocalEngineDialog","Vietinis ClamAV variklis");Dialog(window,"SimpleUpdates","Atnaujinimai");}using(var form=new CaseReviewWindow()){form.Show();Application.DoEvents();Layout(form);form.Font=new Font("Segoe UI",14);Application.DoEvents();Layout(form);form.Close();}using(var form=new DatabaseUpdateWindow()){form.Show();Application.DoEvents();Layout(form);form.Close();}using(var form=new SetupWindow(AppDomain.CurrentDomain.BaseDirectory,true,"")){form.Show();Application.DoEvents();Layout(form);typeof(SetupWindow).GetMethod("CompleteInstallation",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{false});Application.DoEvents();var finish=(Button)typeof(SetupWindow).GetField("install",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);if(!finish.Enabled||finish.Text!="Baigti ir grįžti į diegiklį"||!form.Text.Contains("baigtas"))throw new Exception("Missing explicit setup completion");Layout(form);finish.PerformClick();Application.DoEvents();if(form.Visible||form.DialogResult!=DialogResult.OK)throw new Exception("Finish does not close setup successfully");Console.WriteLine("Setup completion UI: explicit finish button closes modeless setup and returns successful result; native install not invoked.");}using(var form=new PcScanWindow(true)){form.Show();Application.DoEvents();Layout(form);form.Font=new Font("Segoe UI",14);Application.DoEvents();Layout(form);var drive=(CheckedListBox)typeof(PcScanWindow).GetField("drives",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);if(drive.CheckedItems.Count!=1)throw new Exception("disk selection absent");form.Refresh();for(int paint=0;paint<6;paint++){Application.DoEvents();System.Threading.Thread.Sleep(50);}System.IO.File.Copy(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"xfb","Xvfb_screen0"),System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"pc-scan44.xwd"),true);using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"pc-scan44.png"));}form.Close();Console.WriteLine("PC scan UI: disk selection, schedule/load controls, resume explanation and report fit at enlarged font; no native commands invoked.");}Console.WriteLine("Completion UI: readiness, cases, setup, database update and simplified action windows visible with controls in bounds; no native actions executed.");}
}
